// Boardroom Sessions: create a thread, @mention an agent, and get a real
// reply generated by a local model. Skipped when no Ollama model is
// reachable, since every Boardroom reply is a real model call.
import { enterShell, mainText, ollamaHasModels } from '../helpers.mjs';

const TOPIC = 'E2E desktop check';

describe('Alphonso desktop Boardroom', () => {
  before(async function () {
    await enterShell();
    if (!(await ollamaHasModels())) this.skip();
    await $('[data-testid="space-pill-boardroom"]').click();
    await $('[data-testid="sidebar-nav-mission_room"]').click();
  });

  it('creates a thread', async () => {
    const topic = await $('input[placeholder="New thread topic..."]');
    await topic.waitForDisplayed();
    await topic.setValue(TOPIC);
    await $('button*=New Thread').click();
    await $('input[placeholder="Message the room..."]').waitForDisplayed();
    expect(await mainText()).toContain(TOPIC);
  });

  it('gets a real reply from a mentioned agent', async () => {
    const composer = await $('input[placeholder="Message the room..."]');
    // Trailing space closes the @mention autocomplete so Send is not covered.
    await composer.setValue('@Hector In one short sentence, what is your role? ');
    await $('button*=Send').click();
    await browser.waitUntil(async () => (await mainText()).includes('→ Hector'), {
      timeout: 10000,
      timeoutMsg: 'the message was never routed to Hector',
    });
    // A successful reply is labelled with the model and how long it took,
    // e.g. "qwen2.5-coder:7b · 5.8s". First reply can include a model load.
    await browser.waitUntil(async () => /· \d+(\.\d+)?s/.test(await mainText()), {
      timeout: 240000,
      interval: 2000,
      timeoutMsg: 'no agent reply within 4 minutes',
    });
    const text = await mainText();
    expect(text).not.toContain('is thinking…');
    expect(text).not.toContain('Retry');
  });
});
